&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Work Location:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Remote (UK)&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:30,&amp;quot;335559739&amp;quot;:30}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
